const stories = [
 {id:'renovations',topic:'Housing',title:'A new chapter in protecting Toronto renters',summary:'Council adopted a Rental Renovation Licence Bylaw with amendments in November 2024. Read the decision and the steps it set out.',date:'2024-11-14',displayDate:'NOV 14, 2024',scope:'Toronto · City-wide',source:'https://secure.toronto.ca/council/agenda-item.do?item=2024.PH16.4',sourceName:'Council item 2024.PH16.4 · Decision and amendments',impact:'The decision concerns rental renovation licensing and directs public education for tenants and landlords. Individual obligations depend on the full bylaw and applicable circumstances.',detail:'Council adopted the item at its November 13–14, 2024 meeting with amendments. It directed resources and public communications for implementation. Read the adopted recommendations for the full requirements.',events:[['October 16, 2024','Staff report dated.'],['November 13–14, 2024','Council adopted the item with amendments.'],['July 31, 2027','Implementation update requested by this date in the decision. Completion has not been verified here.']]},
 {id:'major-streets',topic:'Housing',title:'More housing options along major streets',summary:'Toronto’s official demonstration plans explain the housing forms enabled by its June 2024 major streets decision.',date:'2024-06-01',displayDate:'JUN 2024',scope:'Toronto · Eligible major streets',source:'https://www.toronto.ca/city-government/planning-development/planning-studies-initiatives/expanding-housing-options/demonstration-plans-for-expanding-housing-options-in-neighbourhoods/',sourceName:'City Planning · Demonstration plans · Major Streets section',impact:'Relevant to residents and property owners along eligible major streets. Site-specific eligibility and current planning requirements must be checked with the City.',detail:'The City’s page records June 2024 adoption of permissions for townhouses up to four storeys and apartment buildings up to six storeys and 60 units along major streets. The page also provides illustrative development plans.',events:[['June 2024','Council adoption recorded on the City’s demonstration-plans page.'],['Source review','Later amendments and individual development approvals are outside this summary.']]},
 {id:'budget',topic:'Budget',title:'Where Toronto’s 2024 budget put public money',summary:'Explore the approved operating budget and the ten-year capital plan through the City’s own budget documents.',date:'2024-01-01',displayDate:'2024',scope:'Toronto · City-wide',source:'https://www.toronto.ca/city-government/budget-finances/city-budget/previous-budgets/2024-city-budget/',sourceName:'City of Toronto · 2024 City Budget · Opening summary',impact:'Relevant to residents using municipal services and people interested in public spending. Program documents provide the detail needed to understand specific services.',detail:'The official page records a $17.1 billion combined tax and rate operating budget and a $49.8 billion ten-year capital budget and plan. These amounts cover different periods and should be read separately.',events:[['2024','Council-approved budget published in the City’s budget archive.'],['Source review','This historical entry does not describe the current annual budget.']]}
];
const menu=[['feed','▤','Feed'],['decisions','▦','Decisions'],['participate','◎','Participate'],['following','♡','Following']];
let saved=[];let storageAvailable=true;try{const value=JSON.parse(localStorage.getItem('ycc-saved')||'[]');saved=Array.isArray(value)?value.filter(id=>stories.some(s=>s.id===id)):[];}catch{storageAvailable=false;}
let filter='All',query='',sort='newest',toastTimer;
const main=document.getElementById('main');
const escapeText=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function announce(message){const toast=document.getElementById('toast');toast.textContent=message;toast.style.opacity=1;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.style.opacity=0,2300);}
function saveButton(id){const active=saved.includes(id);return `<button class="save" data-save="${id}" aria-pressed="${active}">${active?'♥ Saved':'♡ Save'}</button>`;}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('ycc-saved',JSON.stringify(saved));}catch{storageAvailable=false;}render();announce(storageAvailable?(saved.includes(id)?'Story saved':'Story removed'):'Saved for this session only');}
function nav(section){for(const target of ['desktop-nav','mobile-nav'])document.getElementById(target).innerHTML=menu.map(([id,icon,label])=>`<a href="#${id}" class="${section===id?'active':''}" ${section===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span><span>${label}</span></a>`).join('');}
function card(s,index){return `<article class="card ${index===0?'featured':''}"><div class="card-top"><span class="tag">${s.topic}</span><span class="status">Council adopted</span></div><h2><a href="#story/${s.id}">${s.title}</a></h2><p>${s.summary}</p><div class="card-foot"><span>${s.displayDate}<br>${s.scope}</span>${saveButton(s.id)}</div></article>`;}
function results(section){let items=stories.filter(s=>(section!=='following'||saved.includes(s.id))&&(filter==='All'||s.topic===filter)&&`${s.title} ${s.summary} ${s.topic}`.toLowerCase().includes(query.toLowerCase()));items.sort((a,b)=>sort==='newest'?b.date.localeCompare(a.date):a.date.localeCompare(b.date));document.getElementById('results').innerHTML=`<div class="results-label">${items.length} HISTORICAL ${items.length===1?'RECORD':'RECORDS'}</div>`+(items.length?items.map(card).join(''):`<div class="empty"><h2>${section==='following'?'Your interests, in one place.':'No matching stories.'}</h2><p>${section==='following'?'Save a story from the feed to find it here.':'Try another topic or search term.'}</p><button class="button" data-reset>Browse all stories</button></div>`);}
function render(){const route=location.hash.slice(1)||'feed';const [section,id]=route.split('/');nav(section==='story'?'decisions':section);if(section==='category'){renderCategory(id);return;}if(section==='story'){const s=stories.find(s=>s.id===id);if(!s){main.innerHTML='<h1>Story not found</h1><a class="button" href="#feed">Back to feed</a>';return;}main.innerHTML=`<article class="detail"><a href="#feed" class="back">← Back to stories</a><div class="card-top"><span class="tag">${s.topic} · Historical record</span>${saveButton(s.id)}</div><h1>${s.title}</h1><p>${s.scope} · ${s.displayDate}</p><div class="notice">Council adopted · Historical summary. Sources reviewed November 12, 2026. Check official records for subsequent changes.</div><section class="detail-block"><h2>What council decided</h2><p>${s.detail}</p><a class="source" target="_blank" rel="noopener" href="${s.source}">Source: ${s.sourceName} ↗</a></section><section class="detail-block"><h2>Who this could affect</h2><p>${s.impact}</p><a class="source" target="_blank" rel="noopener" href="${s.source}">Check scope and conditions in the official record ↗</a></section><section class="detail-block"><h2>The decision trail</h2><div class="timeline">${s.events.map(([date,event])=>`<p><strong>${date}</strong><br>${event}</p>`).join('')}</div><a class="source" target="_blank" rel="noopener" href="${s.source}">View the source record ↗</a></section><section class="detail-block"><h2>Can I still have a say?</h2><p>This entry describes an adopted decision. No current comment deadline has been verified for this historical item.</p><a class="button" href="#participate">Explore official participation channels ↗</a></section></article>`;return;}
if(section==='participate'){main.innerHTML=`<div class="intro"><span class="eyebrow">TAKE PART</span><h1>Your voice belongs here.</h1><p>Find the right official channel for your question or opinion.</p></div><div class="notice">No open consultation deadlines are verified in this edition. Check the official item page for eligibility and submission dates.</div><article class="card participation"><span class="tag">COUNCIL & COMMITTEES</span><h2>Start with the meeting record</h2><p>Find a current agenda item and read its participation instructions before sending comments or requesting to speak.</p><a class="button" href="https://secure.toronto.ca/council/" target="_blank" rel="noopener">Open Toronto Council portal ↗</a></article><article class="card participation"><span class="tag">PREPARE YOUR INPUT</span><h2>Make your comment specific</h2><p>Identify the agenda item. Explain how the proposal affects you, state the change you want considered, and include relevant evidence.</p><p>Your name and comments become part of the public record. The City asks you to avoid including personal information in comments.</p><a class="source" href="https://www.toronto.ca/city-government/council/council-committee-meetings/participate/" target="_blank" rel="noopener">City of Toronto participation instructions ↗</a></article>`;return;}
const titles={feed:['THE TORONTO EDITION','Your city. In the open.','The decisions shaping your neighbourhood, made easier to understand.'],decisions:['FOLLOW THE PROCESS','Behind every decision.','Read what council adopted and trace it to the original record.'],following:['YOUR READING LIST','Keep what matters close.','Your saved stories, available in this browser.']};const current=titles[section]?section:'feed';const [eyebrow,title,subtitle]=titles[current];main.innerHTML=`<div class="intro"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="notice">Historical edition · 3 curated Toronto decisions from 2024.<br>Sources reviewed Nov 12, 2026. Updates are manual.</div>${!storageAvailable?'<p class="storage-warning">Browser storage unavailable. Saves last for this session.</p>':''}<div class="tools"><input id="search" class="search" type="search" aria-label="Search stories" placeholder="Search decisions, topics…" value="${escapeText(query)}"><select id="sort" aria-label="Sort records"><option value="newest">Newest first</option><option value="oldest">Oldest first</option></select></div><div class="chips" role="group" aria-label="Filter by topic">${['All','Housing','Budget'].map(t=>`<button class="chip ${filter===t?'active':''}" data-topic="${t}" aria-pressed="${filter===t}">${t==='All'?'All topics':t}</button>`).join('')}</div><div id="results" aria-live="polite"></div>`;document.getElementById('sort').value=sort;document.getElementById('search').addEventListener('input',e=>{query=e.target.value;results(current);});document.getElementById('sort').addEventListener('change',e=>{sort=e.target.value;results(current);});results(current);}
main.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){toggleSave(save.dataset.save);return;}const topic=e.target.closest('[data-topic]');if(topic){filter=topic.dataset.topic;render();return;}if(e.target.closest('[data-reset]')){filter='All';query='';if(location.hash==='#feed')render();else location.hash='feed';}});
document.getElementById('about').onclick=()=>document.getElementById('about-dialog').showModal();window.addEventListener('hashchange',()=>{filter='All';query='';render();window.scrollTo(0,0);});

const categoryInfo = {
 transportation: {title:'Transportation', query:'transit transportation', description:'Explore Toronto data about moving around the city.'},
 housing: {title:'Housing & real estate', query:'housing development', description:'Explore city datasets about housing and development.'},
 taxes: {title:'Taxes & budget', query:'budget', description:'Explore city datasets related to public spending.'},
 news: {title:'News', query:'city council', description:'Find official city information and datasets.'},
 infrastructure: {title:'Infrastructure', query:'infrastructure', description:'Explore data about public assets and services.'},
 votes: {title:'Council votes', query:'members of toronto city council voting record', description:'Explore the official recorded-vote dataset. A recorded vote may concern an amendment or a procedural motion.'}
};
async function renderCategory(id){
 const category=categoryInfo[id]; if(!category){location.hash='feed';return;}
 main.innerHTML=`<div class="intro"><span class="eyebrow">TORONTO OPEN DATA</span><h1>${category.title}</h1><p>${category.description}</p></div><div class="notice">Dataset listings are requested from the City of Toronto when this page opens. Dataset refresh times differ. A dataset is not itself a council decision.</div><div id="dataset-results" aria-live="polite">Loading official datasets…</div><section class="detail-block"><h2>Official council records</h2><p>Use the council portal for agendas, decisions, voting details, and amendments. Participation opportunities and deadlines must be checked on the individual agenda item.</p><a class="source" target="_blank" rel="noopener" href="https://secure.toronto.ca/council/">Toronto council and committee portal ↗</a><a class="source" target="_blank" rel="noopener" href="https://www.toronto.ca/city-government/council/council-committee-meetings/participate/">How to participate ↗</a></section>`;
 const container=document.getElementById('dataset-results');
 const api='https://ckan0.cf.opendata.inter.prod-toronto.ca/api/3/action/package_search?q='+encodeURIComponent(category.query)+'&rows=8';
 try {
  const response=await fetch(api,{signal:AbortSignal.timeout(10000)});if(!response.ok)throw new Error('Unavailable');const data=await response.json();if(!data.success||!Array.isArray(data.result?.results))throw new Error('Invalid response');if(!container.isConnected)return;
  const packages=data.result.results.filter(item=>typeof item.name==='string'&&/^[a-z0-9-]+$/.test(item.name));
  container.innerHTML=packages.length?packages.map(item=>`<article class="card"><span class="tag">OFFICIAL DATASET</span><h2>${escapeText(item.title||item.name)}</h2><p>Catalogue last modified: ${escapeText(item.metadata_modified?new Date(item.metadata_modified).toLocaleDateString('en-CA'):'Not available')}. Data refresh may differ.</p><a class="source" href="https://open.toronto.ca/dataset/${encodeURIComponent(item.name)}/" target="_blank" rel="noopener">View dataset, licence and downloads ↗</a></article>`).join(''):'<div class="empty"><p>No matching datasets were returned. Explore the City catalogue directly.</p><a class="source" href="https://open.toronto.ca/" target="_blank" rel="noopener">Open Toronto Open Data ↗</a></div>';
 } catch(error){if(container.isConnected)container.innerHTML=`<div class="empty"><h2>Dataset listings are unavailable</h2><p>The City data service could not be reached from this browser. Please use the official sources below.</p><a class="source" target="_blank" rel="noopener" href="${id==='votes'?'https://open.toronto.ca/dataset/members-of-toronto-city-council-voting-record/':'https://open.toronto.ca/'}">Open ${id==='votes'?'the official voting dataset':'Toronto Open Data'} ↗</a></div>`;}
}
const menuButton=document.getElementById('menu-button');const categoryMenu=document.getElementById('category-menu');const overlay=document.getElementById('menu-overlay');
function setMenu(open){categoryMenu.hidden=!open;overlay.hidden=!open;menuButton.setAttribute('aria-expanded',String(open));if(open)document.getElementById('menu-close').focus();else menuButton.focus();}
menuButton.addEventListener('click',()=>setMenu(categoryMenu.hidden));document.getElementById('menu-close').addEventListener('click',()=>setMenu(false));overlay.addEventListener('click',()=>setMenu(false));categoryMenu.addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!categoryMenu.hidden)setMenu(false)});

render();
